kubectl -n workload-identity delete pod web-gate --ignore-not-found --wait=true
kubectl apply -f - <<'YAML'
{
  "apiVersion": "v1",
  "kind": "Pod",
  "metadata": {
    "name": "web-gate",
    "namespace": "workload-identity",
    "labels": {
      "app": "web-gate"
    }
  },
  "spec": {
    "containers": [
      {
        "name": "web-gate",
        "image": "nginxinc/nginx-unprivileged:alpine",
        "imagePullPolicy": "IfNotPresent",
        "securityContext": {
          "allowPrivilegeEscalation": false
        },
        "ports": [
          {
            "containerPort": 8080,
            "protocol": "TCP"
          }
        ]
      }
    ],
    "securityContext": {
      "runAsNonRoot": true,
      "runAsUser": 101,
      "runAsGroup": 101
    }
  }
}
YAML
kubectl -n workload-identity wait pod/web-gate --for=condition=Ready --timeout=120s
kubectl -n workload-identity exec web-gate -- wget -T 3 -qO- http://127.0.0.1:8080/

sudo mkdir -p /var/lib/kubelet/seccomp/profiles
sudo tee /var/lib/kubelet/seccomp/profiles/no-inspect.json >/dev/null <<'JSON'
{"defaultAction":"SCMP_ACT_ALLOW","syscalls":[{"names":["ptrace","process_vm_readv"],"action":"SCMP_ACT_ERRNO"}]}
JSON
kubectl -n runtime-shield delete pod runtime-web --ignore-not-found --wait=true
kubectl apply -f - <<'YAML'
{
  "apiVersion": "v1",
  "kind": "Pod",
  "metadata": {
    "name": "runtime-web",
    "namespace": "runtime-shield",
    "labels": {
      "app": "runtime-web"
    }
  },
  "spec": {
    "containers": [
      {
        "name": "runtime-web",
        "image": "nginx:1.28-alpine",
        "imagePullPolicy": "IfNotPresent"
      }
    ],
    "securityContext": {
      "seccompProfile": {
        "type": "Localhost",
        "localhostProfile": "profiles/no-inspect.json"
      }
    }
  }
}
YAML
kubectl -n runtime-shield wait pod/runtime-web --for=condition=Ready --timeout=120s
kubectl -n runtime-shield exec runtime-web -- wget -T 3 -qO- http://127.0.0.1/

kubectl apply -f - <<'YAML'
{
  "apiVersion": "networking.k8s.io/v1",
  "kind": "Ingress",
  "metadata": {
    "name": "portal-tls",
    "namespace": "secure-portal",
    "annotations": {
      "nginx.ingress.kubernetes.io/ssl-redirect": "true",
      "nginx.ingress.kubernetes.io/ssl-passthrough": "false"
    }
  },
  "spec": {
    "ingressClassName": "nginx",
    "tls": [
      {
        "hosts": [
          "portal.training.example"
        ],
        "secretName": "portal-cert"
      }
    ],
    "rules": [
      {
        "host": "portal.training.example",
        "http": {
          "paths": [
            {
              "path": "/",
              "pathType": "Prefix",
              "backend": {
                "service": {
                  "name": "portal",
                  "port": {
                    "number": 80
                  }
                }
              }
            }
          ]
        }
      }
    ]
  }
}
YAML
node=$(kubectl get nodes -o jsonpath='{.items[0].status.addresses[?(@.type=="InternalIP")].address}')
http=$(kubectl -n cks001b-ingress get service cks001b-ingress -o jsonpath='{.spec.ports[?(@.name=="http")].nodePort}')
https=$(kubectl -n cks001b-ingress get service cks001b-ingress -o jsonpath='{.spec.ports[?(@.name=="https")].nodePort}')
for attempt in $(seq 1 30); do
  if sudo curl -fsS --noproxy '*' --cacert /root/CKS/portal-ca.crt --resolve "portal.training.example:$https:$node" "https://portal.training.example:$https/" >/dev/null; then break; fi
  sleep 1
done
sudo curl -fsS --noproxy '*' --cacert /root/CKS/portal-ca.crt --resolve "portal.training.example:$https:$node" "https://portal.training.example:$https/"
redirect=$(curl -sS --noproxy '*' --resolve "portal.training.example:$http:$node" -H 'Host: portal.training.example' -o /dev/null -w '%{redirect_url}' "http://portal.training.example:$http/")
case "$redirect" in https://portal.training.example/*|https://portal.training.example:*) ;; *) echo 'HTTPS redirect missing' >&2; exit 1;; esac

